import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
const MONTHS = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const addDays = (date: Date, amount: number) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate() + amount);

const isSameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

const toISODate = (date: Date) =>
  `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const today = startOfDay(new Date());
  const [selected, setSelected] = useState<Date>(() => (value ? startOfDay(value) : today));
  const [visibleMonth, setVisibleMonth] = useState<Date>(
    () => new Date(selected.getFullYear(), selected.getMonth(), 1),
  );

  const days = useMemo(() => {
    const first = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1);
    const leading = (first.getDay() + 6) % 7;
    const gridStart = addDays(first, -leading);
    return Array.from({ length: 42 }, (_, index) => addDays(gridStart, index));
  }, [visibleMonth]);

  const presets = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: addDays(today, -1) },
    { label: 'Неделя назад', date: addDays(today, -7) },
  ];

  const pick = (date: Date) => {
    const next = startOfDay(date);
    setSelected(next);
    setVisibleMonth(new Date(next.getFullYear(), next.getMonth(), 1));
    onChange(next);
  };

  const shiftMonth = (amount: number) => {
    setVisibleMonth((current) => new Date(current.getFullYear(), current.getMonth() + amount, 1));
  };

  return (
    <section
      className="jx-card jx-stack"
      aria-label="Выбор даты отчёта"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3, 12px)' }}
    >
      <div
        className="jx-cluster"
        role="group"
        aria-label="Быстрый выбор"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2, 8px)' }}
      >
        {presets.map((preset) => (
          <Button
            key={preset.label}
            type="button"
            className={isSameDay(preset.date, selected) ? 'jx-btn is-selected' : 'jx-btn'}
            aria-pressed={isSameDay(preset.date, selected)}
            onClick={() => pick(preset.date)}
          >
            {preset.label}
          </Button>
        ))}
      </div>

      <header
        className="jx-cluster"
        style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-space-2, 8px)' }}
      >
        <Button type="button" className="jx-btn" aria-label="Предыдущий месяц" onClick={() => shiftMonth(-1)}>
          ‹
        </Button>
        <strong className="jx-text" aria-live="polite">
          {MONTHS[visibleMonth.getMonth()]} {visibleMonth.getFullYear()}
        </strong>
        <Button type="button" className="jx-btn" aria-label="Следующий месяц" onClick={() => shiftMonth(1)}>
          ›
        </Button>
      </header>

      <div
        className="jx-grid"
        style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 'var(--jx-space-1, 4px)' }}
      >
        {WEEKDAYS.map((weekday) => (
          <span key={weekday} className="jx-text jx-text--muted" style={{ textAlign: 'center' }}>
            {weekday}
          </span>
        ))}

        {days.map((day) => {
          const outside = day.getMonth() !== visibleMonth.getMonth();
          const active = isSameDay(day, selected);
          return (
            <Button
              key={toISODate(day)}
              type="button"
              className={[
                'jx-btn',
                outside ? 'is-muted' : '',
                active ? 'is-selected' : '',
                isSameDay(day, today) ? 'is-today' : '',
              ]
                .filter(Boolean)
                .join(' ')}
              aria-pressed={active}
              aria-current={isSameDay(day, today) ? 'date' : undefined}
              aria-label={toISODate(day)}
              onClick={() => pick(day)}
            >
              {day.getDate()}
            </Button>
          );
        })}
      </div>
    </section>
  );
}

